import logging
import traceback


def _no_traceback_except_hook(etype, value, tb):
    logging.debug("".join(traceback.format_exception_only(etype=etype, value=value)))


class MainExceptionClass(Exception):
    """ Class used for logging exception as error"""
    def __init__(self, exception):
        logging.error(exception)


class MissingMessageExceptionError(Exception):
    """ Raised when message wasn't found in syslog."""
    pass


class DnrAlignmentError(Exception):
    """ Raised when DnR build is different with build on active partition"""
    pass


class WrongBtsStateError(Exception):
    """ Raised when object state is not as expected."""

    def __init__(self, *args, **kwargs):
        super().__init__("\n".join(*args))


class NotAllowedAlarmDetectedError(Exception):
    """ Raised when not allowed alarm was detected during test."""
    pass


class PossibleCrashFoundInSyslogError(Exception):
    """ Raised when possible crash or error found in syslog file."""
    pass


class WftConnectionError(MainExceptionClass):
    """ Raised when error found with connection to WFT."""
    pass


class BlackboxVerificationError(Exception):
    """ Raised when error found in BTS BlackBox file."""
    pass


class UnavailableX2LinkError(Exception):
    """ Raise when X2 Link is not available."""
    pass


class MissingLTEENBObjectError(Exception):
    """ Raise when LTEENB Object is missing."""
    pass


class NotEnoughSpaceError(Exception):
    """ Raised when there is not enough space to continue test."""
    pass


class ResetCounterValueError(Exception):
    """ Raised when reset counter value is other than assumed"""
    pass


class BtslogStartError(Exception):
    """ Raised when btslog is not started"""
    pass


class CriticalAlarmsDetected(MainExceptionClass):
    """ Raised when critical alarm is detected """
    pass


class PduFormatError(Exception):
    """ Raised when PDU format is wrong """
    pass


class LogsCheckError(Exception):
    """ Raised when checking logs fail"""
    pass


class FatalError(Exception):
    """ Raised when fatal error occured"""
    def __init__(self, exception):
        logging.error(exception)
        self.ROBOT_EXIT_ON_FAILURE = True


class SnapshotCollectError(Exception):
    """ Raised when collecting snapshot fail"""
    pass


class NotAllOperationsSucceed(Exception):
    """ Raised when multirunner operations failed"""

    def __init__(self, function_name, exception, failed_nodes):
        super().__init__(f"\nFunction {function_name.__name__} failed"
                         f"\nRaised exception: {exception}"
                         f"\nFailed nodes: {failed_nodes}")


class FunctionTimeoutException(Exception):
    """ Raised when function doesn't finish with success in given time"""

    def __init__(self, function_name, timeout, exception):
        given_timeout = divmod(timeout, 60)
        super().__init__(f"\nFunction {function_name.__name__} doesn't succeed in {given_timeout[0]} minutes"
                         f"{' and ' + str(given_timeout[1]) + ' seconds' if given_timeout[1] else ''}\n")
        self.exception = exception


class ExceptionDeprecationWarning(Exception):

    """ Raised when function is deprecated """
    pass
